'use strict';
// Private Trace workbench decisions. No DOM, storage, network or raw model
// bodies are required. The Host binds returned indexes to its own snapshot.
(()=>{
function boundedWindow(domain, start, end) {
  const span = Math.min(domain.end - domain.start, Math.max(1, end - start));
  const left = Math.max(domain.start, Math.min(start, domain.end - span));
  return { start: left, end: left + span };
}
function zoomWindow(domain, current, factor, anchor = 0.5) {
  const span = (current.end - current.start) * factor, pivot = current.start + (current.end - current.start) * anchor;
  return boundedWindow(domain, pivot - span * anchor, pivot + span * (1 - anchor));
}
function bucketSelection(count, first, last) {
  return { first: Math.max(0, Math.min(count - 1, Math.min(first, last))), last: Math.max(0, Math.min(count - 1, Math.max(first, last))) };
}
function elapsedLabel(microseconds) {
  const ms = Math.max(0, microseconds / 1e3);
  return ms < 1e3 ? `${ms.toFixed(2)}ms` : `${(ms / 1e3).toFixed(2)}s`;
}
function timeMicros(raw) {
  const fraction = raw.match(/\.(\d+)(?:Z|[+-]\d{2}:\d{2})$/)?.[1] ?? "";
  return Date.parse(raw) * 1e3 + Number(fraction.padEnd(6, "0").slice(3, 6));
}
function activityGeometry(buckets) {
  const start = timeMicros(buckets[0].at), end = timeMicros(buckets.at(-1).until), span = Math.max(1, end - start);
  return buckets.map((bucket) => ({ left: (timeMicros(bucket.at) - start) / span, right: (timeMicros(bucket.until) - start) / span }));
}
function activityIndex(geometry, fraction) {
  const index = geometry.findIndex((bucket) => fraction < bucket.right);
  return index < 0 ? geometry.length - 1 : index;
}

function activityInteraction(input){
 const buckets=input.buckets,event=input.event,initial=()=>({drag:null,pinned:false,selected:null,keyboard_start:null,focused:null});
 let state=input.state===null?initial():{...input.state,drag:input.state.drag?{...input.state.drag}:null};
 let tooltip=false,focus=null,navigate=null,labels=null;
 const detail=(first,last=first)=>({first,last,count:buckets.slice(first,last+1).reduce((sum,bucket)=>sum+bucket.count,0),label:input.language==='zh-CN'?'条 Trace':'traces'});
 const preview=(first,last,touch,anchor=null)=>{state.selected=bucketSelection(buckets.length,first,last);state.pinned=touch;tooltip={...detail(state.selected.first,state.selected.last),anchor}};
 const go=range=>{if(detail(range.first,range.last).count>0)navigate=range};
 const indexAt=fraction=>activityIndex(activityGeometry(buckets),Math.max(0,Math.min(1,fraction)));
 switch(event.kind){
 case 'init':state=initial();labels=buckets.map((_,index)=>detail(index));focus=Math.max(0,buckets.findIndex(bucket=>bucket.count>0));tooltip=null;break;
 case 'clear':state=initial();tooltip=null;break;
 case 'outside':if(state.pinned){state=initial();tooltip=null}break;
 case 'focus':state.focused=event.index;tooltip={...detail(event.index),anchor:event.index};break;
 case 'blur':case 'leave':if(!state.pinned&&!state.drag)tooltip=null;break;
 case 'key':{
  const index=state.focused??event.index,key=event.key;
  if(key==='Escape'){state=initial();tooltip=null;break}
  if(key==='Enter'){go(state.selected??{first:index,last:index});break}
  const next=key==='ArrowLeft'?Math.max(0,index-1):key==='ArrowRight'?Math.min(buckets.length-1,index+1):key==='Home'?0:buckets.length-1;
  if(event.shift&&state.keyboard_start===null)state.keyboard_start=index;
  if(!event.shift)state=initial();
  state.focused=next;focus=next;tooltip={...detail(next),anchor:next};
  if(state.keyboard_start!==null)preview(state.keyboard_start,next,true,next);
  break;
 }
 case 'down':{const index=indexAt(event.fraction);state.drag={first:index,last:index,touch:event.touch};preview(index,index,event.touch);break}
 case 'move':{
  const index=indexAt(event.fraction);
  if(state.drag&&event.drag){state.drag.last=index;preview(state.drag.first,index,state.drag.touch)}
  else if(!state.pinned&&!event.touch)tooltip={...detail(index),anchor:index};
  break;
 }
 case 'up':{
  const saved=state.drag;state.drag=null;
  if(saved){const range=bucketSelection(buckets.length,saved.first,saved.last);if(saved.touch)preview(range.first,range.last,true);else go(range)}
  break;
 }
 }
 let selection=null;
 if(state.selected){const range=state.selected,geometry=activityGeometry(buckets);selection={...detail(range.first,range.last),left:geometry[range.first].left,width:geometry[range.last].right-geometry[range.first].left,persistent:state.pinned,explore:state.pinned&&detail(range.first,range.last).count>0}}
 return {state,selection,tooltip,focus,navigate,labels};
}
function validActivityBuckets(buckets){
 return Array.isArray(buckets)&&buckets.length>0&&buckets.length<=48&&buckets.every(bucket=>record(bucket)&&text(bucket.at,128)&&text(bucket.until,128)&&number(Date.parse(bucket.at))&&number(Date.parse(bucket.until))&&Number.isSafeInteger(bucket.count)&&bucket.count>=0);
}
function validActivityInteraction(input){
 if(!record(input)||!validActivityBuckets(input.buckets)||!['en','zh-CN'].includes(input.language)||!record(input.event))return false;
 const n=input.buckets.length,index=value=>Number.isSafeInteger(value)&&value>=0&&value<n,range=value=>record(value)&&index(value.first)&&index(value.last)&&value.first<=value.last,s=input.state,e=input.event;
 if(s!==null&&(!record(s)||s.focused!==null&&!index(s.focused)||typeof s.pinned!=='boolean'||s.keyboard_start!==null&&!index(s.keyboard_start)||s.selected!==null&&!range(s.selected)||s.drag!==null&&(!record(s.drag)||!index(s.drag.first)||!index(s.drag.last)||typeof s.drag.touch!=='boolean')))return false;
 if(s===null&&!['init','clear'].includes(e.kind))return false;
 switch(e.kind){
 case 'init':case 'clear':case 'outside':case 'blur':case 'leave':case 'up':return true;
 case 'focus':return index(e.index);
 case 'key':return index(e.index)&&typeof e.shift==='boolean'&&['ArrowLeft','ArrowRight','Home','End','Enter','Escape'].includes(e.key);
 case 'down':return number(e.fraction)&&typeof e.touch==='boolean';
 case 'move':return number(e.fraction)&&typeof e.touch==='boolean'&&typeof e.drag==='boolean';
 }
 return false;
}

function timelineBrush(domain,current,first,last){
 const span=current.end-current.start,at=fraction=>current.start+Math.max(0,Math.min(1,fraction))*span,x=time=>(time-current.start)/span*1000;
 const start=at(Math.min(first,last)),end=at(Math.max(first,last));
 return {x:x(start),width:Math.abs(x(at(last))-x(at(first))),label:elapsedLabel(start-domain.start)+' – '+elapsedLabel(end-domain.start),start,end};
}
function timelineTooltip(row,domain,language){
 const labels=language==='zh-CN'?{start:'开始',duration:'耗时',ongoing:'仍在执行，尚无结束时间',unknown:'未记录结束时间',first:'首个模型输出'}:{start:'Start',duration:'Duration',ongoing:'Ongoing; end time not recorded',unknown:'End time not recorded',first:'First model output'};
 const lines=[labels.start+' +'+elapsedLabel(row.start-domain.start)];
 lines.push(row.end!==null?labels.duration+' '+elapsedLabel(row.end-row.start):row.running?labels.ongoing:labels.unknown);
 if(row.first_output!==null)lines.push(labels.first+' +'+elapsedLabel(row.first_output-domain.start));
 return lines;
}
function timelineProjection(input){
 const {domain,current,rows,width,has_selected,language}=input;
 const steps=width>=320?4:width>=180?2:1,x=time=>(time-current.start)/(current.end-current.start)*1000;
 const ticks=Array.from({length:steps+1},(_,i)=>elapsedLabel(current.start-domain.start+(current.end-current.start)*i/steps));
 const full=current.start===domain.start&&current.end===domain.end;
 return {ticks,drag_threshold:5,range_label:(language==='zh-CN'?'距 Trace 开始的时间':'Time since trace start')+': '+elapsedLabel(current.start-domain.start)+' – '+elapsedLabel(current.end-domain.start),grid:[0,250,500,750,1000],full,buttons:{in:false,out:full,fit:full,selected:!has_selected},rows:rows.map(row=>{
  const result={bar:null,point:null,first_output:null,tooltip:timelineTooltip(row,domain,language)},start=row.start,end=row.end!==null?row.end:row.running?domain.end:null;
  if(end!==null&&end>start){
   if(end<current.start||start>current.end)return result;
   result.bar={x:Math.max(0,x(start)),width:Math.max(1,Math.min(1000,x(end))-Math.max(0,x(start)))};
  }else if(start>=current.start&&start<=current.end)result.point=x(start);
  if(row.first_output!==null&&row.first_output>=current.start&&row.first_output<=current.end)result.first_output=x(row.first_output);
  return result;
 })};
}
function tree(nodes,rawQuery,closedIDs,language){
 const byId=new Map(nodes.map(node=>[node.id,node]));
 const query=rawQuery.toLocaleLowerCase().trim(),closed=new Set(closedIDs),visible=new Set();
 for(const node of nodes)if(!query||[node.name,node.type,node.id].join(' ').toLocaleLowerCase().includes(query)){
  let current=node,blocked=false;
  for(let depth=0;current&&depth<=nodes.length;depth++){current=byId.get(current.parent);if(current&&closed.has(current.id))blocked=true}
  if(query){current=node;for(let depth=0;current&&depth<=nodes.length;depth++){visible.add(current);current=byId.get(current.parent)}}else if(!blocked)visible.add(node);
 }
 return nodes.map(node=>{
  const button=nodes.some(child=>child.parent===node.id);
  const expanded=query?nodes.some(child=>child.parent===node.id&&visible.has(child)):!closed.has(node.id);
  return {id:node.id,hidden:!visible.has(node),disabled:button?!!query:null,expanded:button?String(expanded):null,label:button?(language==='zh-CN'?(expanded?'收起节点':'展开节点'):(expanded?'Collapse node':'Expand node'))+': '+node.name:null};
 });
}
function columns(storage,unavailable=[]){
 const read=key=>{if(unavailable.includes(key))throw Error('storage unavailable');return storage[key]??'null'};
 let visible=Array(10).fill(true);
 try{
  let saved=JSON.parse(read('steward.trace.columns.v5'));
  if(saved===null){
   let legacy=JSON.parse(read('steward.trace.columns.v4'));
   if(legacy===null){
    let previous=JSON.parse(read('steward.trace.columns.v3'));
    if(previous===null){const older=JSON.parse(read('steward.trace.columns.v2'));if(Array.isArray(older)&&older.length===10)previous=[...older.slice(0,5),true,...older.slice(5)]}
    if(Array.isArray(previous)&&previous.length===11&&previous.every(value=>typeof value==='boolean'))legacy=[previous[0],previous[1],previous[9],...previous.slice(3,9),previous[10]];
   }
   if(Array.isArray(legacy)&&legacy.length===10&&legacy.every(value=>typeof value==='boolean'))saved=[legacy[9],...legacy.slice(0,9)];
  }
  if(Array.isArray(saved)&&saved.length===10&&saved.every(value=>typeof value==='boolean'))visible=saved;
 }catch{}
 return visible;
}
const record=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
const number=value=>typeof value==='number'&&Number.isFinite(value);
const window=value=>record(value)&&number(value.start)&&number(value.end);
const text=(value,max)=>typeof value==='string'&&value.length<=max;
function project(r){
 const input=r.input;
 switch(r.type){
 case 'navigation':{
  if(!record(input)||Object.keys(input).length!==4||['list','current','same_trace','same_selection'].some(key=>typeof input[key]!=='boolean'))throw Error('invalid navigation');
  return {presentation:input.current?'replace':'sheet',keep_filter:input.same_trace,keep_tree_scroll:input.same_trace,keep_detail_scroll:input.same_selection,restore_focus:true,reveal_tabs:true};
 }
 case 'page_controls':{
  if(!record(input)||typeof input.list!=='boolean'||!number(input.width)||input.width<0||typeof input.open!=='boolean'||!record(input.state)||input.state.compact!==null&&typeof input.state.compact!=='boolean'||typeof input.state.wide_open!=='boolean')throw Error('invalid page controls');
  const state={...input.state};let open=input.open;
  if(input.list){const compact=input.width<=760;if(compact!==state.compact){if(compact){state.wide_open=open;open=false}else open=state.wide_open;state.compact=compact}}
  return {open,state,kinds:input.list?['select','trace','identifier','context']:['select','identifier','context'],row:input.list,focus_row:true};
 }
 case 'request_reader':{
  if(!record(input)||!['en','zh-CN'].includes(input.language)||Object.keys(input).length!==1)throw Error('invalid request reader');
  const zh=input.language==='zh-CN';
  return {sections:['system','messages','tools','parameters'],expanded:{system:false,messages:'last',tools:false,tool:false,parameters:false},textRules:{separator:'\n',skipEmpty:true},singleMessage:{roleField:'role',role:'user',contentField:'content'},uppercaseRole:true,capture:['attempt','body'],body:'body',omitted:'omitted',model:'model',instructions:['instructions','system'],messages:['messages','input','contents'],roles:['role','type'],text:'text',content:['content','parts'],tools:'tools',definition:'function',name:'name',exclude:['instructions','system','messages','input','contents','tools'],excerpt:90,labels:{indexPrefix:'[',indexSuffix:'] ',roleSuffix:' · ',request:zh?'请求':'Request',missing:zh?'未记录请求正文。':'Request body was not captured.',system:zh?'系统指令':'System instructions',message:'Message',tool:'Tool',tools:zh?'工具':'Tools',parameters:zh?'参数':'Parameters'}};
 }
 case 'workbench_controls':{
  if(!record(input)||!['formatted','json'].includes(input.mode)||typeof input.input!=='boolean'||typeof input.output!=='boolean'||!['en','zh-CN'].includes(input.language)||!Number.isSafeInteger(input.count)||input.count<0||input.count>1000||!Number.isSafeInteger(input.index)||input.index< -1||input.index>=input.count)throw Error('invalid workbench controls');
  const zh=input.language==='zh-CN';
  return {initial:input.mode,states:{formatted:{mode:'formatted',formatted:true,json:false},json:{mode:'json',formatted:false,json:true}},copies:[{key:'input',disabled:!input.input,reset_label:zh?'复制输入':'Copy input'},{key:'output',disabled:!input.output,reset_label:zh?'复制输出':'Copy output'}],copied:zh?'已复制':'Copied',unavailable:zh?'无法自动复制':'Copy unavailable',reset_ms:1600,previous:input.index>0?input.index-1:null,next:input.index>=0&&input.index+1<input.count?input.index+1:null};
 }
 case 'activity':
  if(!validActivityInteraction(input))throw Error('invalid activity');
  return activityInteraction(input);
 case 'activity_view':{
  if(!record(input)||!Array.isArray(input.buckets)||input.buckets.length===0||input.buckets.length>48||!input.buckets.every(bucket=>record(bucket)&&text(bucket.at,128)&&text(bucket.until,128)&&number(Date.parse(bucket.at))&&number(Date.parse(bucket.until))&&Number.isSafeInteger(bucket.count)&&bucket.count>=0)||!number(input.width)||input.width<0)throw Error('invalid activity view');
  const buckets=input.buckets,first=Date.parse(buckets[0].at),end=Date.parse(buckets.at(-1).until);
  if(end<first)throw Error('invalid activity range');
  return {maximum:Math.max(...buckets.map(bucket=>bucket.count)),axis:{mode:end-first<86400000?'clock':'date',times:(input.width<500?[0,1]:[0,.25,.5,.75,1]).map(position=>new Date(first+(end-first)*position).toISOString())}};
 }
 case 'tree':
  if(!record(input)||!Array.isArray(input.nodes)||input.nodes.length>1000||!text(input.query,4096)||!Array.isArray(input.closed)||input.closed.length>1000||!input.closed.every(id=>text(id,300))||!input.nodes.every(node=>record(node)&&text(node.id,300)&&(node.parent===undefined||text(node.parent,300))&&text(node.name,8192)&&text(node.type,300)))throw Error('invalid tree');
  if(input.language!==undefined&&input.language!=='en'&&input.language!=='zh-CN')throw Error('invalid language');
  return tree(input.nodes,input.query,input.closed,input.language);
 case 'column_controls':{
  if(!record(input)||!['render','toggle'].includes(input.action)||!Array.isArray(input.visible)||input.visible.length!==10||!input.visible.every(value=>typeof value==='boolean'))throw Error('invalid controls');
  const visible=input.visible.slice();
  if(input.action==='toggle'){
   if(!Number.isSafeInteger(input.index)||input.index<0||input.index>=visible.length||typeof input.checked!=='boolean')throw Error('invalid toggle');
   visible[input.index]=input.checked;
  }
  return {visible,indexes:[0,1,2,3,5,6,7,8,9,10],storage_key:'steward.trace.columns.v5',persist:input.action==='toggle'};
 }
 case 'columns':
  if(!record(input)||Object.keys(input).some(key=>!/^steward\.trace\.columns\.v[2-5]$/.test(key)||!text(input[key],16384)))throw Error('invalid columns');
  if(r.unavailable!==undefined&&(!Array.isArray(r.unavailable)||r.unavailable.length>4||!r.unavailable.every(key=>/^steward\.trace\.columns\.v[2-5]$/.test(key))))throw Error('invalid storage status');
  return columns(input,r.unavailable);
 case 'timeline_brush':{
  if(!record(input)||!window(input.domain)||!window(input.current)||input.current.end<=input.current.start||input.current.start<input.domain.start||input.current.end>input.domain.end||!number(input.first)||!number(input.last))throw Error('invalid timeline brush');
  const brush=timelineBrush(input.domain,input.current,input.first,input.last);
  return {x:brush.x,width:brush.width,label:brush.label};
 }
 case 'timeline':{
  const next=project({type:'timeline_window',input});
  return {window:next,projection:project({type:'timeline_projection',input:{...input,current:next}})};
 }
 case 'timeline_projection':
  if(!record(input)||!window(input.domain)||!window(input.current)||input.current.end<=input.current.start||input.current.start<input.domain.start||input.current.end>input.domain.end||!number(input.width)||input.width<0||typeof input.has_selected!=='boolean'||!['en','zh-CN'].includes(input.language)||!Array.isArray(input.rows)||input.rows.length>1000||!input.rows.every(row=>record(row)&&number(row.start)&&(row.end===null||number(row.end))&&typeof row.running==='boolean'&&(row.first_output===null||number(row.first_output))))throw Error('invalid timeline projection');
  return timelineProjection(input);
 case 'timeline_window':{
  if(!record(input)||!window(input.domain)||input.domain.end<=input.domain.start||!window(input.current)||!record(input.action))throw Error('invalid timeline');
  const domain=input.domain,current=input.current,action=input.action,span=current.end-current.start;
  switch(action.kind){
  case 'brush':{
   if(!number(action.first)||!number(action.last))throw Error('invalid brush');
   const brush=timelineBrush(domain,current,action.first,action.last);
   return boundedWindow(domain,brush.start,brush.end);
  }
  case 'restore':return boundedWindow(domain,current.start,current.end);
  case 'button':
   if(!['fit','in','out','selected'].includes(action.action))throw Error('invalid button');
   if(action.action==='fit')return boundedWindow(domain,domain.start,domain.end);
   if(action.action==='selected'){
    if(action.selected===null)return current;
    if(!record(action.selected)||!number(action.selected.start)||action.selected.end!==null&&!number(action.selected.end))throw Error('invalid selection');
    const start=action.selected.start,end=action.selected.end??start,padding=Math.max((end-start)*.15,(domain.end-domain.start)/100);
    return boundedWindow(domain,start-padding,end+padding);
   }
   return zoomWindow(domain,current,action.action==='in'?.5:2);
  case 'key':
   if(!['ArrowLeft','ArrowRight','Home','+','-'].includes(action.key))throw Error('invalid key');
   if(action.key==='Home')return boundedWindow(domain,domain.start,domain.end);
   if(action.key==='ArrowLeft'||action.key==='ArrowRight'){const offset=span*.2*(action.key==='ArrowLeft'?-1:1);return boundedWindow(domain,current.start+offset,current.end+offset)}
   return zoomWindow(domain,current,action.key==='+'?.5:2);
  case 'wheel':
   if(typeof action.pan!=='boolean'||!number(action.delta_y)||!number(action.delta_x)||!number(action.anchor))throw Error('invalid wheel');
   if(action.pan){const offset=span*Math.sign(action.delta_y||action.delta_x)*.1;return boundedWindow(domain,current.start+offset,current.end+offset)}
   return zoomWindow(domain,current,action.delta_y<0?.8:1.25,Math.max(0,Math.min(1,action.anchor)));
  }
  throw Error('unknown timeline action');
 }
 case 'bounded_window':
  if(!record(input)||!window(input.domain)||!number(input.start)||!number(input.end))throw Error('invalid window');
  return boundedWindow(input.domain,input.start,input.end);
 case 'zoom_window':
  if(!record(input)||!window(input.domain)||!window(input.current)||!number(input.factor)||!number(input.anchor))throw Error('invalid zoom');
  return zoomWindow(input.domain,input.current,input.factor,input.anchor);
 case 'bucket_selection':
  if(!record(input)||!Number.isSafeInteger(input.count)||input.count<0||!Number.isSafeInteger(input.first)||!Number.isSafeInteger(input.last))throw Error('invalid buckets');
  return bucketSelection(input.count,input.first,input.last);
 case 'elapsed_label':
  if(!number(input))throw Error('invalid elapsed');
  return elapsedLabel(input);
 case 'time_micros':
  if(!text(input,128)||!Number.isFinite(Date.parse(input)))throw Error('invalid timestamp');
  return timeMicros(input);
 case 'activity_geometry':
  if(!Array.isArray(input)||input.length===0||input.length>1000||!input.every(bucket=>record(bucket)&&text(bucket.at,128)&&text(bucket.until,128)&&Number.isFinite(Date.parse(bucket.at))&&Number.isFinite(Date.parse(bucket.until))))throw Error('invalid geometry');
  return activityGeometry(input);
 case 'activity_index':
  if(!record(input)||!Array.isArray(input.geometry)||input.geometry.length>1000||!input.geometry.every(bucket=>record(bucket)&&number(bucket.left)&&number(bucket.right))||!number(input.fraction))throw Error('invalid index');
  return activityIndex(input.geometry,input.fraction);
 }
 throw Error('unknown operation');
}
self.onmessage=event=>{
 const r=event.data;
 try{
  if(!record(r)||!Number.isSafeInteger(r.seq)||r.seq<1)throw Error('invalid envelope');
  self.postMessage({seq:r.seq,type:r.type,result:project(r)});
 }catch{self.postMessage({seq:Number.isSafeInteger(r?.seq)&&r.seq>0?r.seq:0,type:'failed'})}
};
})();

stylesheet.source:
.obs-activity{border-bottom:1px solid var(--border)}
.obs-activity-heading{display:flex;justify-content:space-between;font-size:12px}
.obs-activity-heading strong{font-weight:500}
.obs-activity-heading span{color:var(--muted-foreground)}
.obs-activity-chart svg{display:block;width:100%;height:100%;overflow:visible}
.obs-activity-axis{display:flex;justify-content:space-between;padding-top:3px;font-size:11px;color:var(--muted-foreground)}
.obs-activity-chart rect{fill:var(--trace-agent);opacity:.55}
.obs-activity{padding:12px 12px 8px}
.obs-activity-heading{margin-bottom:12px}
.obs-activity-plot{display:grid;grid-template-columns:28px minmax(0,1fr);gap:8px}
.obs-activity-y{display:flex;flex-direction:column;justify-content:space-between;padding:0 0 1px;color:var(--muted-foreground);font-size:11px;text-align:right;font-variant-numeric:tabular-nums}
.obs-activity-chart{position:relative;display:flex;align-items:stretch;gap:2px;height:88px;padding:0;border-bottom:1px solid var(--border);touch-action:pan-y;user-select:none}
.obs-activity-bucket{position:relative;display:flex;align-items:flex-end;flex:1;min-width:0;text-decoration:none;outline-offset:-1px}
.obs-activity-bucket:hover,.obs-activity-bucket:focus-visible{background:var(--hover)}
.obs-activity-bucket:focus-visible{outline:2px solid var(--focus)}
.obs-activity-brush{position:absolute;inset-block:0;background:color-mix(in srgb,var(--trace-agent) 16%,transparent);border-inline:1px solid var(--trace-agent);pointer-events:none}
.obs-activity-axis{margin-left:36px;gap:8px;height:24px}
.obs-activity-axis span{white-space:nowrap}
.obs-activity-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:22px;color:var(--muted-foreground);font-size:11px}
.obs-activity-empty{margin:14px 0;color:var(--muted-foreground);font-size:12px}
@media(max-width:760px){.obs-activity-footer{font-size:12px;flex-wrap:wrap}
.obs-activity-axis span{font-size:11px}}
.obs-activity-bucket{height:100%}
.obs-activity-bucket>svg{display:block;width:100%;height:100%;pointer-events:none}
.obs-activity-bucket rect{fill:var(--trace-agent);opacity:.65}
.obs-activity-bucket:hover rect,.obs-activity-bucket:focus-visible rect{opacity:1}
.obs-activity-chart>.obs-activity-bars{display:block;width:100%;height:100%;overflow:hidden}
.obs-activity-bars .obs-activity-bucket{display:inline;height:auto}
.obs-activity-bucket:focus-visible rect{stroke:var(--focus);stroke-width:2;vector-effect:non-scaling-stroke}
.obs-activity-footer>output{flex:1;min-width:150px;font-size:12px;line-height:1.6;white-space:pre-line;overflow-wrap:anywhere;color:var(--foreground)}

/* Trace list, messages and detail presentation. */
.obs-list-toolbar{display:flex;align-items:center;gap:6px}
.obs-column-options{display:grid;gap:2px}
.obs-column-options label{display:flex;align-items:center;gap:8px;min-height:28px;margin:0;color:var(--foreground)}
.obs-time-presets{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}
.obs-col-role{width:105px}
.obs-col-name{width:185px}
.obs-col-preview{width:260px}
.obs-col-duration{width:85px}
.obs-col-model{width:140px}
.obs-col-status{width:100px}
.obs-trace-list .obs-number{text-align:right}
.trace-open{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;min-width:0;margin:0}
.trace-open{font-weight:400;text-decoration:none}
.trace-open:hover{text-decoration:underline}
.obs-task-link{font-size:var(--text-ui);margin:0 0 18px;color:var(--muted-foreground)}
.obs-task-link a{color:var(--foreground)}
.obs-trace-identity{overflow-wrap:anywhere}
.root-boundary{font-size:var(--text-ui)}
.task-timeline{padding-left:18px}
.task-timeline li{margin:7px 0}
.obs-pane-note,.obs-privacy-note{font-size:var(--text-meta);line-height:1.7;color:var(--muted-foreground);overflow-wrap:anywhere}
.obs-pane-note{margin:10px 0 16px}
.obs-privacy-note{margin:16px 0}
.obs-json{padding:14px;border:1px solid var(--border);border-radius:8px;background:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;font:var(--text-meta)/1.75 var(--font-code);tab-size:2}
.obs-more{display:inline-block;margin:16px 8px;font-size:var(--text-ui)}
.obs-loading{opacity:.7}
.obs-message{border:1px solid var(--border);border-radius:8px;margin:10px 0;overflow:hidden}
.obs-message summary{display:flex;align-items:center;gap:8px;padding:10px 12px;background:var(--muted);font-size:var(--text-meta)}
.obs-message summary>span:last-child{margin-left:auto;color:var(--muted-foreground)}
.obs-message-role{text-transform:uppercase;font-size:var(--text-meta);font-weight:600}
.obs-message-text{white-space:pre-wrap;overflow-wrap:anywhere;font-size:var(--text-ui);line-height:1.75;padding:14px}
.obs-call-card{margin:10px;padding:12px;background:var(--muted);border:1px solid var(--border);border-radius:7px;font-size:var(--text-meta)}
.obs-call-card pre{font-size:var(--text-meta);margin:8px 0 0}
.obs-input-preview-block{font-size:var(--text-ui);margin:22px 0}
.obs-input-preview-block>summary{font-weight:550}
.obs-metadata{border-top:1px solid var(--border);padding-top:16px;margin-top:26px}
.obs-selected-id{font-size:var(--text-meta);overflow-wrap:anywhere}
.obs-json{padding:10px;font-size:11px;line-height:1.6;border-radius:6px}
.obs-message-text,.obs-input-preview-block{font-size:12px}
.control-sheet #observability-workbench{height:100%}
.observability>#observability-workbench{height:calc(100dvh - 128px);min-height:480px}
.observability>#observability-workbench>.obs-workbench{height:100%;min-height:0}
@container inspection-layout (max-width:700px){.observability>#observability-workbench{height:auto;min-height:0}}
@media(max-width:760px){.obs-column-options label{min-height:44px}.control-sheet #observability-workbench{height:auto}}
.obs-full-heading{padding:0 16px 12px}
.obs-full-heading h1{font-size:18px;margin:0}
.obs-tree-pane[data-timeline] .tree-heading{grid-template-columns:minmax(0,1fr) 80px;gap:6px}
@container inspection-layout (max-width:560px){.control-sheet #observability-workbench{height:auto}}
.obs-detail-toolbar .control-segmented{margin-bottom:5px}
.obs-io-section{margin-bottom:18px}
.obs-io-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}
.obs-io-heading h3{margin:0}
.obs-io-output{--json-surface:color-mix(in srgb,var(--status-ready) 5%,var(--card))}
.obs-io-output .obs-message{background:var(--json-surface)}
.obs-input-preview-block{margin:0}
.obs-input-preview-block>summary{font-size:11px;color:var(--muted-foreground);font-weight:400}
.obs-message summary{padding:6px 10px}
.obs-message-text{font-size:12px;padding:10px;line-height:1.7}
.obs-provider-evidence{font-size:11px;border-top:1px solid var(--border);padding-top:12px;margin:18px 0}
.js .obs-trace-list tr[data-execution-id]{cursor:pointer}

/* Trace tree nodes, states and decorative guides. */
.obs-tree{list-style:none;padding:0;margin:0}
.obs-tree li{margin:0;padding:0}
.obs-tree li>small{display:block;font-size:var(--text-meta);margin:0 10px 8px;color:var(--muted-foreground)}
.obs-tree a.tree-heading{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(65px,1fr);gap:12px;align-items:center;padding:10px 9px;border-radius:7px;min-height:43px;text-decoration:none;font-size:var(--text-ui)}
.obs-tree a.tree-heading:hover{background:var(--muted)}
.obs-tree a[aria-current=true]{background:var(--muted);font-weight:550}
.obs-node-label{display:flex;align-items:flex-start;gap:6px;min-width:0}
.obs-indent{min-width:7px;max-width:7px}
.obs-type-icon{color:var(--muted-foreground);font-size:var(--text-ui)}
.obs-node-content{display:flex;flex:1;flex-direction:column;min-width:0}
.obs-node-name{display:block;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.obs-node-status{display:flex;align-items:center;gap:5px;font-size:var(--text-meta);line-height:1.65;font-weight:400;color:var(--muted-foreground)}
.obs-status-dot{font-size:6px;color:var(--success)}
.obs-node-status[data-status=failed],.obs-node-status[data-status=http_error],.obs-node-status[data-status=unknown]{color:var(--danger)}
.obs-node-status:is([data-status=failed],[data-status=http_error],[data-status=unknown]) .obs-status-dot{color:var(--danger)}
.obs-node-status[data-status=waiting],.obs-node-status[data-status=pending]{color:var(--warning)}
.obs-node-status:is([data-status=waiting],[data-status=pending]) .obs-status-dot{color:var(--warning)}
.obs-node-time{display:flex;align-items:center;gap:7px;min-width:0}
.obs-node-time svg{display:block;width:100%;height:13px;min-width:20px}
.obs-node-time small{font-size:var(--text-meta);font-weight:400;color:var(--muted-foreground);white-space:nowrap;min-width:30px;text-align:right}
.obs-track{stroke:var(--border);stroke-width:1}
.obs-bar{fill:var(--muted-foreground)}
.obs-tree [aria-current=true] .obs-bar{fill:var(--foreground)}
.obs-kind{font-size:var(--text-meta)!important;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--foreground)!important;border-radius:5px;background:var(--muted);padding:4px 7px}
.obs-detail-facts{font-size:var(--text-meta);color:var(--muted-foreground);margin-bottom:8px}
.obs-tree-search{margin:4px 0 8px}
.obs-tree a.tree-heading{grid-template-columns:minmax(0,1fr);gap:0;min-height:40px;padding:5px 6px;border-radius:4px;font-size:12px}
.obs-node-label{gap:6px;align-items:start}
.obs-indent{min-width:12px;max-width:12px;align-self:stretch;border-left:1px solid var(--border)}
.obs-node-content{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:0 4px}
.obs-node-name{font-size:12px;line-height:18px;font-weight:500}
.obs-node-duration{font-size:11px;line-height:16px;color:var(--muted-foreground)}
.obs-node-status{grid-row:1;grid-column:2;max-width:76px;overflow:hidden;font-size:10px;line-height:18px}
.obs-node-time{display:none}
.obs-type-icon{display:flex;margin-top:2px}
.obs-type-icon svg{width:14px;height:14px}
.obs-kind{font-size:10px!important;padding:2px 4px}
.obs-detail-facts{font-size:11px;margin:0 0 12px}
@media(max-width:760px){.obs-tree a.tree-heading{min-height:44px}}
.obs-tree-pane[data-timeline] .obs-node-time{display:flex;min-width:0}
.obs-tree-pane[data-timeline] .obs-node-time svg{display:block;width:100%;height:12px}
.obs-tree-pane[data-timeline] .obs-node-time small{display:none}
.observation-node{--node-color:var(--muted-foreground)}
.observation-node[data-observation-type=agent]{--node-color:var(--trace-agent)}
.observation-node[data-observation-type=generation]{--node-color:var(--trace-generation)}
.observation-node[data-observation-type=tool]{--node-color:var(--trace-tool)}
.observation-node[data-observation-kind=http]{--node-color:var(--trace-http)}
.observation-node[data-observation-kind=retriever]{--node-color:var(--trace-retriever)}
.obs-type-icon,.obs-node-duration{color:var(--node-color)}
.obs-bar{fill:var(--node-color)}
.obs-tree-row{display:flex;align-items:stretch;min-width:0;min-height:44px;position:relative}
.obs-tree a.tree-heading{flex:1;min-width:0}
.obs-tree [aria-current=true]{background:color-mix(in srgb,var(--node-color) 10%,var(--background))}
.obs-tree-guides{display:flex;align-self:stretch;flex:none}
.obs-tree-guides>span{width:12px;flex:none;position:relative}
.obs-tree-guides>span[data-continue=true]::before{content:"";position:absolute;inset:0 auto 0 5px;border-left:1px solid var(--border)}
.obs-tree-guides>span:last-child[data-continue=false]::before{content:"";position:absolute;inset:0 auto 50% 5px;border-left:1px solid var(--border)}
.obs-tree-guides>span:last-child::after{content:"";position:absolute;left:5px;right:0;top:50%;border-top:1px solid var(--border)}
.obs-tree-toggle-space{width:20px;flex:none}
.obs-node-status[data-status=completed],.obs-node-status[data-status=succeeded]{color:var(--status-ready)}
.obs-node-status:is([data-status=completed],[data-status=succeeded]) .obs-status-dot{color:var(--status-ready)}
.obs-node-status:is([data-status=queued],[data-status=unknown]){color:var(--status-attention)}
@media(max-width:760px){.obs-tree-toggle-space{width:44px}}
.observation-node[data-observation-kind=wait]{--node-color:var(--status-attention)}
.obs-node-status:is([data-status=queued],[data-status=unknown]) .obs-status-dot{color:var(--status-attention)}

/* Request evidence and generation metrics. */
.obs-wire-reader{display:grid;gap:20px}
.obs-wire-attempt{min-width:0}
.obs-wire-attempt>.obs-message{margin:10px 0}
.obs-wire-attempt>.obs-message>summary{white-space:nowrap;text-overflow:ellipsis;overflow:hidden}
.obs-wire-attempt .obs-message-text{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.75 var(--font-ui);padding:14px}
.obs-wire-attempt .obs-json{max-height:480px;overflow:auto}
.obs-message-excerpt{min-width:0;flex:1;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;color:var(--muted-foreground);font-weight:400}
.obs-message[open]>.obs-message-excerpt{display:none}

.obs-model-name{font-size:12px;color:var(--muted-foreground);margin-top:14px}
.obs-model-name strong{color:var(--foreground);font-weight:500;margin-left:6px;overflow-wrap:anywhere}
.obs-generation-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px 12px;margin:16px 0 0;padding-top:14px;border-top:1px solid var(--border);font-variant-numeric:tabular-nums}
.obs-generation-metrics>div{min-width:0}
.obs-generation-metrics dt{display:flex;align-items:center;gap:4px;font-size:11px;color:var(--muted-foreground)}
.obs-generation-metrics dd{margin:5px 0 0;font-size:12px;font-weight:500;overflow-wrap:anywhere}
.obs-evidence-links{display:flex;flex-wrap:wrap;gap:8px 16px;margin:12px 0 20px;font-size:12px}
.obs-evidence-links a{color:var(--muted-foreground)}
.obs-evidence-links [aria-current=page]{color:var(--foreground);font-weight:500}
.obs-internal-filter{margin:4px 4px 10px;font-size:11px;color:var(--muted-foreground)}




.obs-timing-events{list-style:none;padding:0;margin:0;font-size:12px}
.obs-timing-events li{display:flex;flex-wrap:wrap;gap:6px 12px;padding:10px 0;border-bottom:1px solid var(--border)}
.obs-timing-events time{margin-left:auto;font-variant-numeric:tabular-nums}
.obs-timing-events small{width:100%;font-size:11px;color:var(--muted-foreground);overflow-wrap:anywhere}
.obs-message[open]>summary .obs-message-excerpt{display:none}
@container inspection-layout (max-width:950px){.obs-generation-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:760px){.obs-generation-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.obs-evidence-links a,.obs-internal-filter a{display:inline-flex;align-items:center;min-height:44px}}
.obs-model-name{display:flex;align-items:center;gap:6px}
.obs-model-name strong{margin-left:0}
.obs-model-name .control-help{margin-left:auto}
.obs-generation-metrics dt{line-height:16px}
.obs-generation-metrics dd{line-height:18px}
.obs-diagnostic-identity{margin-bottom:20px}

/* Trace timeline; same frozen workbench resource. */
#observability-workbench{display:flex;flex-direction:column;min-height:0}
.obs-run-overview{display:flex;flex:none;flex-wrap:wrap;align-items:center;gap:8px 18px;padding:10px 16px;border-bottom:1px solid var(--border);font-size:11px;color:var(--muted-foreground);font-variant-numeric:tabular-nums}
.obs-run-overview>span{display:flex;align-items:center;gap:6px}
.obs-run-overview strong{font-size:12px;font-weight:500;color:var(--foreground)}
.obs-run-overview .obs-run-errors,.obs-run-overview .obs-run-errors strong{color:var(--danger)}
.observability>#observability-workbench>.obs-workbench{height:auto;min-height:0;flex:1}
.obs-tree-pane{--timeline-width:44%}
.obs-timeline-controls{position:sticky;top:-8px;z-index:4;background:var(--background);padding-top:8px;margin-top:-8px}
.obs-timeline-actions{display:flex;align-items:center;gap:0}
.obs-timeline-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 0;border-bottom:1px solid var(--border);font-size:10px;color:var(--muted-foreground)}
.obs-timeline-axis{width:var(--timeline-width);display:flex;justify-content:space-between;gap:2px;min-width:0;white-space:nowrap;font-size:10px;font-variant-numeric:tabular-nums;touch-action:pan-y}
.obs-timeline-axis:focus-visible{outline:2px solid var(--focus)}
.obs-timeline-axis span:nth-child(even){display:none}
.obs-tree a.tree-heading{display:block;padding-right:calc(var(--timeline-width) + 6px);min-height:44px}
.obs-node-content{display:block;min-width:0}
.obs-node-content .obs-node-duration{display:none}
.obs-node-status{max-width:none;font-size:10px;line-height:16px}
.obs-node-name{line-height:18px}
.obs-node-time{position:absolute;inset:0 0 0 auto;width:var(--timeline-width);display:flex;align-items:center;min-width:0;touch-action:pan-y;user-select:none}
.obs-node-time svg{width:100%;height:24px;display:block;overflow:hidden}
.obs-bar,.obs-point{fill:var(--node-color);stroke:var(--node-color);vector-effect:non-scaling-stroke;stroke-width:1}
.obs-point{stroke-width:2}
.obs-timeline-grid{stroke:var(--border);stroke-width:1;vector-effect:non-scaling-stroke}
.observation-node[data-running] .obs-bar{fill:color-mix(in srgb,var(--node-color) 10%,var(--background));stroke-dasharray:3 2}
.obs-first-output{stroke:var(--foreground);stroke-width:2;vector-effect:non-scaling-stroke}
.obs-timeline-brush{fill:color-mix(in srgb,var(--trace-agent) 18%,transparent);pointer-events:none}

.obs-generation-metrics{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px 8px}
.obs-generation-metrics dt{min-height:32px;align-items:flex-end}
.obs-generation-metrics dd{margin-top:4px}
@container observation-detail (max-width:340px){.obs-generation-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.obs-generation-metrics dt{min-height:16px}}
@media(min-width:1500px){.obs-timeline-axis span:nth-child(even){display:block}}
@media(max-width:760px){.obs-run-overview{padding:10px 12px;gap:6px 14px}.obs-timeline-actions{gap:0}.obs-timeline-heading{padding:6px 0}.obs-timeline-axis{font-size:11px}.obs-timeline-axis span:nth-child(2n){display:none}.obs-timeline-axis span:first-child,.obs-timeline-axis span:last-child{display:block}}
.obs-tree [aria-current=true] .obs-bar{fill:var(--node-color)}
.obs-tree-pane .obs-timeline-axis span:nth-child(n){display:block}
.obs-timeline-heading>.obs-internal-filter{margin:0;flex:1;min-width:0}
.obs-timeline-heading{padding:4px 0}

template.source:
{{define "observability-page"}}
<section class="observability" id="observability-page"{{if .Trace.ReaderRevision}} data-trace-reader-revision="{{.Trace.ReaderRevision}}"{{end}}{{if .Trace.WorkbenchManaged}} data-trace-program-revision="{{.Trace.ReaderRevision}}"{{end}}>
{{with .Trace}}
{{if .Tree}}
<a class="back-link" href="{{traceListURL .}}">{{traceTr "← Traces"}}</a><div class="obs-full-heading"><h1>{{.Tree.Trace.Title}}</h1></div>
{{with .Relations}}{{with .Task}}<p class="obs-task-link"><a href="{{taskURL .Ref}}">{{.Title}}</a> {{traceTr "· Task execution"}} {{if $.Trace.Tree.Trace.Epoch}}{{traceTr "· epoch"}} {{$.Trace.Tree.Trace.Epoch}}{{end}}</p>{{end}}{{end}}
<div id="observability-workbench">{{template "trace-workbench" $}}</div>
{{else}}
{{if .Task}}
<h1 class="sr-only">{{traceTr "Traces"}}</h1>
 {{with .Relations}}<section class="panel obs-task-epochs">{{with .Task}}<h2 aria-label="{{.Title}}">{{.Title}}{{template "help" (help "trace-epochs-help" (traceTr "Task") (traceTr "Each continuation creates a separate Root epoch. Main creation is a causal link, not Worker ancestry."))}}</h2><a href="{{taskURL .Ref}}">{{traceTr "Open task →"}}</a>{{end}}<div class="object-list">{{range .Executions}}{{if eq .Role "root"}}<a class="object-row" href="{{traceURL $.Trace "run" .ID}}"><strong>{{traceTr "Root Worker · epoch"}} {{.Epoch}}</strong><span class="status-pill control-status-badge" data-status="{{.Status}}">{{traceTr .Status}}</span></a>{{end}}{{end}}</div></section>{{end}}
{{else}}
<form id="trace-filters" class="obs-filters" data-auto-filter method="get" action="/developer/observability" aria-label="{{traceTr "Filter traces"}}">
<div class="obs-list-heading control-list-heading"><h1>{{traceTr "Tracing"}}</h1></div>
 <div class="control-search obs-search control-list-search">{{template "icon-search"}}<input type="search" name="search" value="{{.Query.Search}}" maxlength="200" placeholder="{{traceTr "Search name, ID or model…"}}" aria-label="{{traceTr "Search traces"}}"><button type="submit" class="control-icon-button" aria-label="{{traceTr "Search traces"}}">{{template "icon-arrow-right"}}</button></div>

{{if .Query.Session}}<input type="hidden" name="session" value="{{.Query.Session}}">{{end}}
<div class="control-list-toolbar obs-table-toolbar"><button type="button" class="secondary control-toolbar-button" data-list-filter-toggle="trace-filter-rail" hidden>{{template "icon-filter"}}<span>{{traceTr "Filters"}}</span></button><details class="control-disclosure" data-control-disclosure><summary>{{template "icon-columns"}}<span>{{traceTr "Columns"}}</span></summary><div class="control-disclosure-panel"><h2>{{traceTr "Visible columns"}}</h2><div class="obs-column-options"><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Trace ID"}}" data-trace-column="0" checked disabled> {{traceTr "Trace ID"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Created time"}}" data-trace-column="1" checked disabled> {{traceTr "Created time"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Type"}}" data-trace-column="2" checked disabled> {{traceTr "Type"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Status"}}" data-trace-column="3" checked disabled> {{traceTr "Status"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Output"}}" data-trace-column="4" checked disabled> {{traceTr "Output"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Wall time"}}" data-trace-column="5" checked disabled> {{traceTr "Wall time"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "TTFT"}}" data-trace-column="6" checked disabled> {{traceTr "TTFT"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Model"}}" data-trace-column="7" checked disabled> {{traceTr "Model"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Tokens"}}" data-trace-column="8" checked disabled> {{traceTr "Tokens"}}</label><label><input type="checkbox" aria-label="{{traceTr "Show column"}}: {{traceTr "Model cost"}}" data-trace-column="9" checked disabled> {{traceTr "Model cost"}}</label></div></div></details></div>
<div class="obs-results-layout">
<details id="trace-filter-rail" class="obs-filter-rail" open><summary>{{template "icon-filter"}}<span>{{traceTr "Filters"}}</span>{{template "icon-chevron"}}</summary><div class="obs-filter-rail-content">
