{{if .List.Activity}}{{$activityFirst := index .List.Activity 0}}{{$activityStart := unixMicro $activityFirst.At}}{{$activityEnd := $activityStart}}{{$activityMax := intSub 1 0}}{{range .List.Activity}}{{$activityEnd = unixMicro .Until}}{{if gt .Count $activityMax}}{{$activityMax = .Count}}{{end}}{{end}}{{$activitySpan := intSub $activityEnd $activityStart}}<div class="obs-activity-plot"><div class="obs-activity-y" aria-hidden="true"><span data-activity-max></span><span>0</span></div><div class="obs-activity-chart" aria-label="{{traceTr "Trace count over time"}}"><svg class="obs-activity-bars" viewBox="0 0 1000 100" preserveAspectRatio="none" aria-label="{{traceTr "Trace count over time"}}">{{range $index,$bucket:=.List.Activity}}{{$activityLeft := fraction 0 1 1}}{{$activityRight := fraction 0 1 1}}{{if gt $activitySpan 0}}{{$activityLeft = fraction (intSub (unixMicro .At) $activityStart) $activitySpan 1000}}{{$activityRight = fraction (intSub (unixMicro .Until) $activityStart) $activitySpan 1000}}{{end}}{{if .Count}}<a class="obs-activity-bucket" data-bucket="{{$index}}" href="{{traceRangeURL $.Trace .At .Until}}" aria-label="{{.At}} – {{.Until}} · {{.Count}} {{traceTr "traces"}}"><title>{{.At}} – {{.Until}} · {{.Count}} {{traceTr "traces"}}</title><rect x="{{$activityLeft}}" y="{{floatSub 100 (fraction .Count $activityMax 100)}}" width="{{if gt $activityRight $activityLeft}}{{floatSub $activityRight $activityLeft}}{{else}}0{{end}}" height="{{fraction .Count $activityMax 100}}"/></a>{{else}}<g class="obs-activity-bucket" data-bucket="{{$index}}"><rect x="{{$activityLeft}}" y="100" width="{{if gt $activityRight $activityLeft}}{{floatSub $activityRight $activityLeft}}{{else}}0{{end}}" height="0"/></g>{{end}}{{end}}</svg><div class="obs-activity-brush" hidden></div></div></div><div class="obs-activity-axis" aria-hidden="true"></div><div class="obs-activity-footer"><span data-activity-hint>{{traceTr "Click a bar or drag to filter time"}}</span><output data-activity-selection aria-live="polite" hidden></output><a class="button secondary" data-activity-explore hidden>{{traceTr "Explore this window"}}</a></div>{{else}}<p class="obs-activity-empty">{{traceTr "No traces in this time range."}}</p>{{end}}
</section>
<section class="obs-trace-list" aria-label="{{traceTr "Traces"}}"><div class="obs-table-scroll" tabindex="0" role="region" aria-label="{{traceTr "Trace results"}}"><table class="control-list-table"><colgroup><col class="obs-col-id"><col class="obs-col-created"><col class="obs-col-role"><col class="obs-col-status"><col class="obs-col-preview" data-trace-required><col class="obs-col-preview"><col class="obs-col-duration"><col class="obs-col-duration"><col class="obs-col-model"><col class="obs-col-tokens"><col class="obs-col-cost"></colgroup><thead><tr><th scope="col">{{traceTr "Trace ID"}}</th><th scope="col" aria-sort="descending">{{traceTr "Created time"}}</th><th scope="col">{{traceTr "Type"}}</th><th scope="col">{{traceTr "Status"}}</th><th scope="col">{{traceTr "Trace"}}</th><th scope="col">{{traceTr "Output"}}</th><th scope="col">{{traceTr "Wall time"}}</th><th scope="col" aria-label="TTFT">TTFT {{template "help" (help "trace-ttft-help" "TTFT" (traceTr "First model call: request start to first text, reasoning or tool-call output, including retries. Missing timing displays unknown."))}}</th><th scope="col">{{traceTr "Model"}}</th><th scope="col" class="obs-number" title="{{traceTr "Input / output"}}">{{traceTr "Tokens"}}</th><th scope="col" class="obs-number" aria-label="{{traceTr "Model cost"}}">{{traceTr "Model cost"}} {{template "help" (help "trace-cost-help" (traceTr "Model cost") (traceTr "Model cost includes recorded charges when available; otherwise reference API price estimates. Estimates are not invoices; subscription charges may differ."))}}</th></tr></thead><tbody>
{{range .List.Items}}<tr data-execution-id="{{.ID}}" data-role="{{.Role}}"><td>{{template "identifier" (identifier "" .ID "")}}</td><td><span class="obs-cell-text">{{traceTime .CreatedAt}}</span></td><td><span class="control-kind-badge" data-kind="agent" title="{{template "trace-role-label" .Role}}">{{template "trace-role-label" .Role}}</span></td><td><span class="status-pill control-status-badge" data-status="{{.Status}}">{{traceTr .Status}}</span></td><td><a class="trace-open obs-cell-text" href="{{traceURL $.Trace "run" .ID}}" title="{{template "trace-title-label" .}}">{{template "trace-title-label" .}}</a></td><td><p class="obs-cell-text" title="{{.Output}}">{{if .Output}}{{.Output}}{{else}}<span class="muted">—</span>{{end}}</p></td><td>{{traceTr (elapsed .CreatedAt .EndedAt)}}</td><td>{{milliseconds .Metrics.TTFTMS}}</td><td><span class="obs-cell-text" title="{{.Model}}">{{.Model}}</span></td><td class="obs-number">{{if .Metrics.KnownUsage}}{{totalInput .Metrics}} / {{.Metrics.Output}}{{else}}<span class="muted" title="{{traceTr "Usage unknown"}}">—</span>{{end}}</td><td class="obs-number">{{template "trace-cost" .Metrics}}</td></tr>{{else}}<tr><td colspan="11"><div class="empty-state"><h2>{{traceTr "No matching traces"}}</h2><p>{{traceTr "Try another search or adjust your filters."}}</p><a href="/developer/observability">{{traceTr "Clear all"}}</a></div></td></tr>{{end}}</tbody></table></div></section>
