ode-label"><span class="obs-type-icon">{{template "observation-type-icon" .Observation}}</span><span class="obs-node-content"><span class="obs-node-name" title="{{traceTr .Name}}">{{traceTr .Name}}</span><small class="obs-node-duration">{{duration .Started .Ended}}</small><span class="obs-node-status" title="{{traceTr .Status}}" data-status="{{.Status}}"><span class="obs-status-dot" aria-hidden="true">●</span><span>{{traceTr .Status}}</span></span></span></span><span class="obs-node-time" aria-hidden="true"><svg viewBox="0 0 1000 24" preserveAspectRatio="none"><line x1="0" y1="12" x2="1000" y2="12" class="obs-track"/>{{if or .Ended .Running}}<rect x="{{.X}}" y="7" width="{{.Width}}" height="10" rx="2" class="obs-bar"/>{{else}}<circle cx="{{.X}}" cy="12" r="3" class="obs-point"/>{{end}}</svg></span></a></div>{{if .ParentOutside}}<small>{{traceTr "Parent outside page ·"}} <a class="obs-select" href="{{traceURL $.Trace "obs" .Parent}}">{{traceTr "open parent"}}</a></small>{{end}}</li>{{end}}</ol>
