{{else if eq $.Trace.Tab "diff"}}
 <h3>{{traceTr "Adjacent input diff"}}</h3><nav class="section-tabs compact" aria-label="{{traceTr "Compare section"}}"><a class="obs-select" href="{{traceURL $.Trace "compare" "messages"}}" {{if eq $.Trace.Compare "messages"}}aria-current="page"{{end}}>{{traceTr "Messages"}}</a><a class="obs-select" href="{{traceURL $.Trace "compare" "tools"}}" {{if eq $.Trace.Compare "tools"}}aria-current="page"{{end}}>{{traceTr "Tools"}}</a></nav>
 {{with $.Trace.Diff}}{{if .Previous}}<p class="muted">{{traceTr "Step"}} {{.Previous}} → {{$.Trace.Tree.Selected.Step}} {{traceTr "· exact saved"}} {{traceTr $.Trace.Compare}}</p><ol class="context-diff">{{range .Items}}<li data-change="{{.Kind}}"><strong>{{.Kind}}</strong> · {{.Label}}{{if ne .Before nil}} · <a href="{{contextURL $.Trace.Tree.Selected.RunID $.Trace.ReaderRevision}}&amp;step={{$.Trace.Diff.Previous}}&amp;section={{$.Trace.Compare}}&amp;item={{.Before}}">{{traceTr "Before ["}}{{.Before}}]</a>{{end}}{{if ne .After nil}} · <a href="{{contextURL $.Trace.Tree.Selected.RunID $.Trace.ReaderRevision}}&amp;step={{$.Trace.Tree.Selected.Step}}&amp;section={{$.Trace.Compare}}&amp;item={{.After}}">{{traceTr "After ["}}{{.After}}]</a>{{end}}</li>{{else}}<li>{{traceTr "No differences on this page."}}</li>{{end}}</ol>{{if .Next}}<a class="obs-select" href="{{traceURL $.Trace "diff_after" .Next}}">{{traceTr "More changes →"}}</a>{{end}}{{else}}<p class="obs-empty">{{traceTr "This is the first saved round; there is no earlier input to compare."}}</p>{{end}}{{end}}
{{else if eq .Type "generation"}}
<section class="obs-io-section obs-io-input"><div class="obs-io-heading"><h3>{{traceTr "Input"}}</h3><button type="button" class="control-icon-button" data-copy-json="input" aria-label="{{traceTr "Copy input"}}" disabled>{{template "icon-copy"}}</button></div><div data-formatted-only> <p class="obs-detail-note">{{if $.Trace.InputComplete}}{{len $.Trace.Messages}} {{traceTr "messages · complete saved content"}}{{else}}{{traceTr "Input exceeds the inline reading limit. Use JSON pagination or Frozen context for complete content."}}{{end}}</p><div class="obs-messages">{{range $.Trace.Messages}}<details class="obs-message role-{{.Role}}" {{if ne .Role "system"}}open{{end}}><summary><span class="obs-message-role">{{traceTr .Role}}</span>{{if .Source}}<small>{{.Source}}</small>{{end}}<span>[{{.Index}}]</span><span class="obs-message-excerpt">{{.Text}}</span></summary><div class="obs-message-text">{{.Text}}</div>{{if .CallID}}{{template "identifier" (identifier "Tool call" .CallID "")}}{{end}}{{if .Calls}}<pre class="obs-call-card" data-readonly-json>{{prettyBody .Calls}}</pre>{{end}}{{range .Images}}{{template "identifier" (identifier "Image" . "")}}{{end}}{{if .More}}<a class="obs-select obs-detail-note" href="{{traceURL $.Trace "tab" "context"}}">{{traceTr "Read full message →"}}</a>{{end}}</details>{{end}}</div></div><div data-json-only hidden>{{with $.Trace.Input}}{{if .Available}}<pre class="obs-json" data-readonly-json data-json-source="input">{{prettyBody .Content}}</pre>{{if .Next}}<a class="obs-select" href="{{traceURL $.Trace "input" .Next}}">{{traceTr "Continue input →"}}</a>{{end}}{{else}}<p class="obs-empty">{{traceTr "No saved input."}}</p>{{end}}{{end}}</div></section><section class="obs-io-section obs-io-output"><div class="obs-io-heading"><h3 aria-label="{{traceTr "Accepted response"}}">{{traceTr "Output"}}{{if not $.Trace.ModelOutput}}{{with $.Trace.Output}}{{if and .Available .Note}}{{template "help" (help "observation-output-help" (traceTr "Output") (traceTr .Note))}}{{end}}{{end}}{{end}}</h3><button type="button" class="control-icon-button" data-copy-json="output" aria-label="{{traceTr "Copy output"}}" disabled>{{template "icon-copy"}}</button></div><div data-formatted-only>{{with $.Trace.ModelOutput}}<article class="obs-message role-assistant"><div class="obs-message-text">{{.Text}}</div>{{range .ToolCalls}}<div class="obs-call-card"><strong>{{.Name}}</strong><pre>{{prettyBody .Arguments}}</pre></div>{{end}}{{if .Clipped}}<p class="obs-detail-note">{{traceTr "Saved output was clipped; this is not a complete upstream answer."}}</p>{{end}}</article>{{else}}{{template "observation-output" $}}{{end}}
</div><div data-json-only hidden>{{template "observation-output" $}}</div></section>
<nav class="obs-evidence-links" aria-label="{{traceTr "Input evidence"}}"><a class="obs-select" href="{{traceURL $.Trace "tab" "context"}}">{{traceTr "Frozen context, tools & sources"}}</a><a class="obs-select" href="{{traceURL $.Trace "tab" "wire"}}">{{traceTr "Provider request"}}</a></nav>
{{else}}
<section class="obs-io-section obs-io-input"><div class="obs-io-heading"><h3 aria-label="{{traceTr "Input"}}">{{traceTr "Input"}}{{with $.Trace.Input}}{{if .Note}}{{template "help" (help "observation-input-help" (traceTr "Input") (traceTr .Note))}}{{end}}{{end}}</h3><button type="button" class="control-icon-button" data-copy-json="input" aria-label="{{traceTr "Copy input"}}" disabled>{{template "icon-copy"}}</button></div>{{with $.Trace.Input}}{{if .Available}}<pre class="obs-json" data-readonly-json data-json-source="input">{{prettyBody .Content}}</pre>{{if .Next}}<a class="obs-select" href="{{traceURL $.Trace "input" .Next}}">{{traceTr "Continue input →"}}</a>{{end}}{{else}}<p class="obs-empty">{{traceTr "No saved input."}}</p>{{end}}{{end}}</section><section class="obs-io-section obs-io-output"><div class="obs-io-heading"><h3 aria-label="{{traceTr "Output"}}">{{traceTr "Output"}}{{with $.Trace.Output}}{{if and .Available .Note}}{{template "help" (help "observation-output-help" (traceTr "Output") (traceTr .Note))}}{{end}}{{end}}</h3><button type="button" class="control-icon-button" data-copy-json="output" aria-label="{{traceTr "Copy output"}}" disabled>{{template "icon-copy"}}</button></div>{{template "observation-output" $}}</section>
{{end}}
{{if eq $.Trace.Tab "metadata"}}<details class="technical-details obs-metadata" open><summary>{{traceTr "Raw observation"}}</summary><p class="obs-selected-id">{{template "identifier" (identifier "ID" .Key "")}}</p>{{if .Parent}}<p data-observation-parent>{{traceTr "Parent"}} {{template "identifier" (identifier "" .Parent (traceURL $.Trace "obs" .Parent))}}</p>{{end}}<pre class="obs-json">{{obsJSON .}}</pre></details>{{end}}
{{end}}{{end}}{{end}}
{{define "observation-output"}}{{if .Trace.ToolOutput}}<div data-formatted-only>{{with .Trace.ToolOutput}}{{if .Error}}<p class="feedback error">{{.Error.Code}} · {{.Error.Message}}</p>{{else}}{{range .Texts}}<pre class="obs-json" data-readonly-json>{{prettyBody .}}</pre>{{end}}{{end}}{{range .Artifacts}}{{template "identifier" (identifier "Artifact" . "")}}{{end}}{{range .Images}}{{template "identifier" (identifier "Image" . "")}}{{end}}{{end}}</div><div data-json-only hidden>{{template "observation-output-raw" .}}</div>{{else}}{{template "observation-output-raw" .}}{{end}}{{end}}
{{define "observation-output-raw"}}{{with .Trace.Output}}{{if .Available}}<pre class="obs-json" data-readonly-json data-json-source="output">{{prettyBody .Content}}</pre>{{if .Next}}<a class="obs-select" href="{{traceURL $.Trace "output" .Next}}">{{traceTr "Continue output →"}}</a>{{end}}{{else}}<div class="control-help-line obs-empty">{{traceTr "No accepted output"}}{{template "help" (help "missing-output-help" (traceTr "Output") (printf "%s %s" (traceTr "No accepted output recorded. Pending, failed and unknown results are not successful empty responses.") (traceTr .Note)))}}</div>{{end}}{{end}}{{end}}

{{define "generation-metrics"}}
{{with .Trace}}<div class="obs-model-name">{{traceTr "Model"}} <strong>{{with .Tree.Generation}}{{if .Model}}{{.Model}}{{else}}—{{end}}{{else}}—{{end}}</strong>{{template "help" (help "generation-metrics-help" (traceTr "Model call metrics") (traceTr "TTFT includes retries and tool-call output. Output speed uses first output to stream terminal in the terminal attempt. Input tokens include cache read and write; missing evidence remains unknown."))}}</div>
<dl class="obs-generation-metrics" aria-label="{{traceTr "Model call metrics"}}">
<div><dt>{{traceTr "Latency"}}</dt><dd>{{duration .Tree.Selected.Started .Tree.Selected.Ended}}</dd></div>
<div><dt>TTFT</dt><dd>{{milliseconds .TTFTMS}}</dd></div>
<div><dt>{{traceTr "Output speed"}}</dt><dd>{{tokenRate .OutputRate}}</dd></div>
{{with .Tree.Generation}}<div><dt>{{traceTr "Model cost"}}</dt><dd>{{template "trace-cost" .Metrics}}</dd></div>
<div><dt>{{traceTr "Input tokens"}}</dt><dd>{{if .Metrics.KnownUsage}}{{totalInput .Metrics}}{{else}}—{{end}}</dd></div>
<div><dt>{{traceTr "Output tokens"}}</dt><dd>{{if .Metrics.KnownUsage}}{{.Metrics.Output}}{{else}}—{{end}}</dd></div>
<div><dt>{{traceTr "Cached input tokens"}}</dt><dd>{{if .Metrics.KnownUsage}}{{.Metrics.CacheRead}}{{else}}—{{end}}</dd></div>
<div><dt>{{traceTr "Cache write tokens"}}</dt><dd>{{if .Metrics.KnownUsage}}{{.Metrics.CacheWrite}}{{else}}—{{end}}</dd></div>{{end}}
</dl>{{end}}
{{end}}
{{define "provider-timing"}}<section class="obs-provider-timing"><h3>{{traceTr "Provider timing"}}</h3>{{with .Trace.Tree.ProviderTimings}}<ol class="obs-timing-events">{{range .}}<li><span>{{template "trace-provider-timing-label" .Phase}}</span><time>{{observedAt .At}}</time>{{if .HTTPStatus}}<span>HTTP {{.HTTPStatus}}</span>{{end}}{{if .ErrorCode}}<span>{{.ErrorCode}}</span>{{end}}<small>{{.Attempt}}</small></li>{{end}}</ol>{{else}}<p class="obs-empty">{{traceTr "Provider timing was not recorded for this generation."}}</p>{{end}}</section>{{end}}

{{define "trace-role-label"}}{{if eq . "main"}}{{traceTr "Main"}}{{else if eq . "root"}}{{traceTr "Root Worker"}}{{else if eq . "child"}}{{traceTr "Child Worker"}}{{else}}{{traceTr "Execution"}}{{end}}{{end}}
{{define "trace-tab-label"}}{{if eq . "overview"}}{{traceTr "Input / Output"}}{{else if eq . "metadata"}}{{traceTr "Details"}}{{else if eq . "context"}}{{traceTr "Context"}}{{else if eq . "wire"}}{{traceTr "Requests"}}{{else if eq . "diff"}}{{traceTr "Compare"}}{{else}}{{traceTr .}}{{end}}{{end}}
{{define "trace-title-label"}}{{if and (eq .Role "main") (nonblank .Input)}}{{.Input}}{{else}}{{.Title}}{{end}}{{end}}
{{define "trace-provider-timing-label"}}{{if eq . "started"}}{{traceTr "HTTP request sent"}}{{else if eq . "headers"}}{{traceTr "Response headers received"}}{{else if eq . "error"}}{{traceTr "HTTP request failed"}}{{else if eq . "first_body"}}{{traceTr "First response data"}}{{else if eq . "first_text"}}{{traceTr "First model text"}}{{else if eq . "first_tool_call"}}{{traceTr "First model tool call"}}{{else if eq . "stream_terminal"}}{{traceTr "Provider stream terminal event"}}{{else if eq . "header_timeout"}}{{traceTr "Response headers timed out"}}{{else if eq . "stream_idle_timeout"}}{{traceTr "Response stream idle timeout"}}{{else if eq . "generation_deadline"}}{{traceTr "Generation time limit reached"}}{{end}}{{end}}
{{define "trace-observation-role"}}{{if eq . "Main"}}main{{else if eq . "Root Worker"}}root{{else if eq . "Child Worker"}}child{{end}}{{end}}
{{define "trace-observation-kind"}}{{if eq .Name "Provider HTTP"}}http{{else if and (eq .Type "span") (or (eq .Timing "approval wait") (eq .Timing "observed wait"))}}wait{{else}}{{.Type}}{{end}}{{end}}
{{define "trace-parent-run"}}{{trimPrefix . "agent:"}}{{end}}
{{define "trace-task-action"}}{{if eq . "create"}}{{traceTr "Created Task"}}{{else if eq . "append"}}{{traceTr "Appended instruction"}}{{else if eq . "pause"}}{{traceTr "Paused Task"}}{{else if eq . "cancel"}}{{traceTr "Cancelled Task"}}{{else if eq . "complete"}}{{traceTr "Completed Task"}}{{else}}{{traceTr "Recorded Task action"}}{{end}}{{end}}

